import java.util.*;

public class Main {
    String build(String s) {
        StringBuilder result = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (c == '#') {
                if (result.length() > 0) result.deleteCharAt(result.length() - 1);     // backspace: remove the last typed character, if any
            } else {
                result.append(c);
            }
        }
        return result.toString();
    }

    boolean backspaceCompare(String s, String t) {
        return build(s).equals(build(t));                                                // simulate both strings fully, then compare the results
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.backspaceCompare("ab#c", "ad#c"));
        System.out.println(solution.backspaceCompare("a#c", "b"));
    }
}

