string build(string s) {
    string result;
    for (char c : s) {
        if (c == '#') {
            if (!result.empty()) result.pop_back();                                     // backspace: remove the last typed character, if any
        } else {
            result.push_back(c);
        }
    }
    return result;
}

bool backspaceCompare(string s, string t) {
