def get_next_valid_index(s, i):
    skip = 0
    while i >= 0:
        if s[i] == '#':
            skip += 1                                                      # a '#' cancels the character before it
            i -= 1
        elif skip > 0:
            skip -= 1                                                      # this character IS cancelled by a pending '#'
            i -= 1
        else:
            break                                                          # found a genuinely surviving character (or i < 0)
    return i

def backspace_compare(s, t):
    i, j = len(s) - 1, len(t) - 1
    while i >= 0 or j >= 0:
        i = get_next_valid_index(s, i)                                     # walk backward to the next surviving character in s
        j = get_next_valid_index(t, j)                                     # walk backward to the next surviving character in t
        if i >= 0 and j >= 0:
            if s[i] != t[j]:
                return False                                                # the surviving characters at this position differ
        elif i >= 0 or j >= 0:
            return False                                                    # one string has a surviving character, the other doesn't
        i -= 1
        j -= 1
    return True


if __name__ == "__main__":
    print(backspace_compare("ab#c", "ad#c"))
    print(backspace_compare("a#c", "b"))

