import java.util.*;

public class Main {
    int getNextValidIndex(String s, int i) {
        int skip = 0;
        while (i >= 0) {
            if (s.charAt(i) == '#') {
                skip++;                                                                 // a '#' cancels the character before it
                i--;
            } else if (skip > 0) {
                skip--;                                                                  // this character IS cancelled by a pending '#'
                i--;
            } else {
                break;                                                                    // found a genuinely surviving character (or i < 0)
            }
        }
        return i;
    }

    boolean backspaceCompare(String s, String t) {
        int i = s.length() - 1, j = t.length() - 1;
        while (i >= 0 || j >= 0) {
            i = getNextValidIndex(s, i);                                                     // walk backward to the next surviving character in s
            j = getNextValidIndex(t, j);                                                      // walk backward to the next surviving character in t
            if (i >= 0 && j >= 0) {
                if (s.charAt(i) != t.charAt(j)) return false;                                    // the surviving characters at this position differ
            } else if (i >= 0 || j >= 0) {
                return false;                                                                     // one string has a surviving character, the other doesn't
            }
            i--;
            j--;
        }
        return true;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.backspaceCompare("ab#c", "ad#c"));
        System.out.println(solution.backspaceCompare("a#c", "b"));
    }
}

